#include <iostream>
#include <fstream>
using namespace std;

int maxCzynnikPierwszy(int n) {
    int maxP = 1;
    for (int d = 2; d * d <= n; d++) {
        while (n % d == 0) {
            maxP = d;
            n /= d;
        }
    }
    if (n > 1) maxP = n;
    return maxP;
}

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int suma = 0;
    int najLiczba = 0, najMax = 1000000;

    cout << "a) Najwieksze czynniki pierwsze:" << endl;
    while (plik >> liczba) {
        int mp = maxCzynnikPierwszy(liczba);
        cout << liczba << " -> max czynnik: " << mp << endl;
        suma += mp;
        if (mp < najMax) {
            najMax = mp;
            najLiczba = liczba;
        }
    }

    cout << endl << "b) Suma najwiekszych czynnikow: " << suma << endl;
    cout << endl << "c) Najgladsza liczba: " << najLiczba
         << " (max czynnik: " << najMax << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Faktoryzacja przez dzielenie: dzielimy n przez d=2,3,... az d*d > n. Kazde d, ktore dzieli n, jest czynnikiem pierwszym (bo mniejsze czynniki juz zostaly wyeliminowane). Jesli po petli n > 1, to n jest najwiekszym czynnikiem pierwszym. "Gladka" liczba to taka o malym najwiekszym czynniku.

